import { Option } from "effect";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  numberFieldButtonClassName,
  numberFieldGroupClassName,
  numberFieldInputClassName,
  numberFieldRootClassName,
  numberFieldScrubAreaClassName,
  numberFieldScrubAreaCursorClassName,
} from "./view";

export {
  numberFieldButtonClassName,
  numberFieldGroupClassName,
  numberFieldInputClassName,
  numberFieldRootClassName,
  numberFieldScrubAreaClassName,
  numberFieldScrubAreaCursorClassName,
} from "./view";

export type NumberFieldStyle = Readonly<Record<string, string>>;

export type NumberFieldState = Readonly<{
  disabled?: boolean | undefined;
  invalid?: boolean | undefined;
  focused?: boolean | undefined;
}>;

export type RootViewConfig = NumberFieldState &
  Readonly<{
    children: readonly Html[];
    className?: string | undefined;
    style?: NumberFieldStyle | undefined;
  }>;

export type ScrubAreaViewConfig<ParentMessage> = NumberFieldState &
  Readonly<{
    id?: string | undefined;
    testId?: string | undefined;
    children: readonly Html[];
    onPointerDown?: (screenX: number) => ParentMessage;
    onPointerMove?: (screenX: number) => ParentMessage;
    onPointerUp?: ParentMessage | undefined;
    className?: string | undefined;
    style?: NumberFieldStyle | undefined;
  }>;

export type ScrubAreaCursorViewConfig = NumberFieldState &
  Readonly<{
    children: readonly Html[];
    className?: string | undefined;
    style?: NumberFieldStyle | undefined;
  }>;

export type GroupViewConfig = NumberFieldState &
  Readonly<{
    children: readonly Html[];
    className?: string | undefined;
    style?: NumberFieldStyle | undefined;
  }>;

export type ButtonViewConfig<ParentMessage> = NumberFieldState &
  Readonly<{
    ariaLabel: string;
    onClick: ParentMessage;
    children: readonly Html[];
    className?: string | undefined;
    style?: NumberFieldStyle | undefined;
  }>;

export type InputViewConfig<ParentMessage> = NumberFieldState &
  Readonly<{
    id: string;
    value: string;
    onInput: (value: string) => ParentMessage;
    ariaLabel: string;
    labelledById?: string | undefined;
    min?: number | undefined;
    max?: number | undefined;
    step?: number | undefined;
    className?: string | undefined;
    style?: NumberFieldStyle | undefined;
  }>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  state: NumberFieldState
) => [
  ...(state.disabled === true ? [h.DataAttribute("disabled", "")] : []),
  ...(state.invalid === true ? [h.DataAttribute("invalid", "")] : []),
  ...(state.invalid === false ? [h.DataAttribute("valid", "")] : []),
  ...(state.focused === true ? [h.DataAttribute("focused", "")] : []),
];

export const rootView = <ParentMessage>({
  children,
  className,
  style,
  ...state
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(numberFieldRootClassName, className)),
    ],
    children
  );
};

export const scrubAreaView = <ParentMessage>({
  id,
  testId,
  children,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  className,
  style,
  ...state
}: ScrubAreaViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      ...(testId === undefined ? [] : [h.DataAttribute("testid", testId)]),
      ...(onPointerDown === undefined
        ? []
        : [
            h.OnPointerDown(
              (_pointerType, _button, screenX) =>
                Option.some(onPointerDown(screenX))
            ),
          ]),
      ...(onPointerMove === undefined
        ? []
        : [
            h.OnPointerMove((screenX) =>
              Option.some(onPointerMove(screenX))
            ),
          ]),
      ...(onPointerUp === undefined
        ? []
        : [h.OnPointerUp(() => Option.some(onPointerUp))]),
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(numberFieldScrubAreaClassName, className)),
    ],
    children
  );
};

export const scrubAreaCursorView = <ParentMessage>({
  children,
  className,
  style,
  ...state
}: ScrubAreaCursorViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(numberFieldScrubAreaCursorClassName, className)),
    ],
    children
  );
};

export const groupView = <ParentMessage>({
  children,
  className,
  style,
  ...state
}: GroupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(numberFieldGroupClassName, className)),
    ],
    children
  );
};

const buttonView = <ParentMessage>({
  ariaLabel,
  onClick,
  children,
  className,
  style,
  ...state
}: ButtonViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel(ariaLabel),
      h.OnClick(onClick),
      ...(state.disabled === true ? [h.Disabled(true)] : []),
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(numberFieldButtonClassName, className)),
    ],
    children
  );
};

export const decrementView = <ParentMessage>(
  config: ButtonViewConfig<ParentMessage>
): Html => buttonView(config);

export const incrementView = <ParentMessage>(
  config: ButtonViewConfig<ParentMessage>
): Html => buttonView(config);

export const inputView = <ParentMessage>({
  id,
  value,
  onInput,
  ariaLabel,
  labelledById,
  min,
  max,
  step,
  className,
  style,
  ...state
}: InputViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.input([
    h.Id(id),
    h.Type("number"),
    h.Value(value),
    h.OnInput(onInput),
    h.AriaLabel(ariaLabel),
    ...(labelledById === undefined
      ? []
      : [h.Attribute("aria-labelledby", labelledById)]),
    ...(min === undefined ? [] : [h.Attribute("min", String(min))]),
    ...(max === undefined ? [] : [h.Attribute("max", String(max))]),
    ...(step === undefined ? [] : [h.Attribute("step", String(step))]),
    ...(state.invalid === undefined
      ? []
      : [h.Attribute("aria-invalid", state.invalid ? "true" : "false")]),
    ...(state.disabled === true ? [h.Disabled(true)] : []),
    ...stateAttributes(h, state),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(classNames(numberFieldInputClassName, className)),
  ]);
};

export const numberFieldRootClassName = "grid max-w-sm gap-2";

export const numberFieldScrubAreaClassName =
  "inline-flex w-fit cursor-ew-resize items-center gap-1 text-sm font-medium text-gray-950 select-none";

export const numberFieldScrubAreaCursorClassName =
  "hidden text-gray-950 sm:block";

export const numberFieldGroupClassName =
  "inline-flex h-10 w-fit items-center overflow-hidden rounded-md border border-gray-300 bg-white shadow-sm data-[disabled]:bg-gray-50";

export const numberFieldButtonClassName =
  "grid size-10 place-items-center text-lg font-medium text-gray-700 transition-colors hover:bg-gray-50 disabled:cursor-not-allowed disabled:text-gray-400";

export const numberFieldInputClassName =
  "h-10 w-20 border-x border-gray-200 bg-transparent px-3 text-center text-sm text-gray-950 outline-none aria-[invalid=true]:text-red-700 disabled:cursor-not-allowed disabled:text-gray-500";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as NumberField from ".";

const view = (value: string) => {
  const h = html<string>();
  const labelId = "amount-label";

  return NumberField.rootView<string>({
    children: [
      NumberField.scrubAreaView({
        id: labelId,
        children: [h.span([], ["Amount"])],
      }),
      NumberField.groupView({
        children: [
          NumberField.decrementView({
            ariaLabel: "Decrease",
            onClick: String(Number(value) - 1),
            children: [h.span([], ["-"])],
          }),
          NumberField.inputView({
            id: "amount",
            value,
            onInput: (nextValue) => nextValue,
            ariaLabel: "Amount",
            labelledById: labelId,
            min: 0,
            step: 1,
          }),
          NumberField.incrementView({
            ariaLabel: "Increase",
            onClick: String(Number(value) + 1),
            children: [h.span([], ["+"])],
          }),
        ],
      }),
    ],
  });
};

describe("NumberField registry component", () => {
  test("renders amount input with increment and decrement controls", () => {
    Scene.scene(
      {
        update: (model: string, message: string) => [message, []] as const,
        view,
      },
      Scene.with("100"),
      Scene.expect(Scene.text("Amount")).toExist(),
      Scene.expect(Scene.role("spinbutton", { name: "Amount" })).toHaveValue(
        "100"
      ),
      Scene.click(Scene.role("button", { name: "Increase" })),
      Scene.expect(Scene.role("spinbutton", { name: "Amount" })).toHaveValue(
        "101"
      ),
      Scene.click(Scene.role("button", { name: "Decrease" })),
      Scene.expect(Scene.role("spinbutton", { name: "Amount" })).toHaveValue(
        "100"
      )
    );
  });

  test("exports Base UI anatomy class hooks", () => {
    expect(NumberField.numberFieldRootClassName).toContain("grid");
    expect(NumberField.numberFieldInputClassName).toContain(
      "aria-[invalid=true]"
    );
  });
});
